package com.pradeep.finance.importing;
import java.math.BigDecimal; import java.time.LocalDate; import java.time.format.DateTimeFormatter; import java.util.regex.*; import org.springframework.stereotype.Component;
@Component public class BankOfAmericaCardSummaryExtractor implements StatementSummaryExtractor {
 private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("MM/dd/uuuu"); private static final Pattern BAL=Pattern.compile("New Balance Total \\$([\\d,]+\\.\\d{2})"); private static final Pattern MIN=Pattern.compile("Total Minimum Payment Due \\$([\\d,]+\\.\\d{2})"); private static final Pattern DUE=Pattern.compile("Payment Due Date (\\d{2}/\\d{2}/\\d{4})"); private static final Pattern LIMIT=Pattern.compile("Total Credit Line \\$([\\d,]+\\.\\d{2})"); private static final Pattern AVAIL=Pattern.compile("Total Credit Available \\$([\\d,]+\\.\\d{2})"); private static final Pattern CLOSE=Pattern.compile("Statement Closing Date (\\d{2}/\\d{2}/\\d{4})");
 public boolean supports(String t){return t.contains("Visa Signature")&&t.contains("Total Credit Line");} public StatementSummary extract(String t){return new StatementSummary(a(BAL,t),a(LIMIT,t),a(AVAIL,t),a(Pattern.compile("Fees Charged \\$([\\d,]+\\.\\d{2})"),t),a(Pattern.compile("Interest Charged \\$([\\d,]+\\.\\d{2})"),t),a(MIN,t),d(DUE,t),null,d(CLOSE,t));} private BigDecimal a(Pattern p,String t){Matcher m=p.matcher(t);return m.find()?new BigDecimal(m.group(1).replace(",","")):null;} private LocalDate d(Pattern p,String t){Matcher m=p.matcher(t);return m.find()?LocalDate.parse(m.group(1),DATE):null;}}
